# Number of 4- and 8-connected components in test's 7 mask, and for masks split by lines.
def comps(mask, adj=4):
    unseen=set(mask); outc=[]
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    if adj==8: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
    while unseen:
        s=unseen.pop(); stack=[s]; comp={s}
        while stack:
            r,c=stack.pop()
            for dr,dc in dirs:
                p=(r+dr,c+dc)
                if p in unseen: unseen.remove(p);comp.add(p);stack.append(p)
        outc.append(comp)
    return outc
